def translate_legacy_run(request):
    if request.get('protocol') != 'ibm-acp-legacy': raise ValueError('unsupported legacy protocol')
    if not request.get('tenant_id') or not request.get('session_id') or not request.get('run_id'):
        raise ValueError('tenant, session and run IDs are required')
    return {'protocolVersion':'1.0.0','contextId':request['session_id'],'legacyRunId':request['run_id'],'tenantId':request['tenant_id'],'message':request['message'],'idempotencyKey':request['tenant_id']+':'+request['run_id']}
